using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Windows.Forms;
namespace CircuitoStudio {
 public sealed class MotorStartingForm:Form {
  readonly Project project;readonly Board board;readonly Circuit circuit;readonly Dictionary<string,TextBox> numbers=new Dictionary<string,TextBox>();readonly ComboBox phases=new ComboBox();readonly TextBox reference=new TextBox();
  public bool Changed {get;private set;}
  public MotorStartingForm(Project p,Board b,Circuit c){if(p==null||b==null||c==null||!p.Boards.Contains(b)||!b.Circuits.Contains(c)||c.ChildBoardId!="")throw new InvalidDataException("Selecione um circuito terminal do projeto.");project=p;board=b;circuit=c;Text="Motor — rendimento e partida";ClientSize=new Size(760,720);MinimumSize=new Size(700,640);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;ShowInTaskbar=false;
   var note=new Label{Dock=DockStyle.Top,Height=112,Padding=new Padding(16),Text=c.Id+" · "+c.Name+"\r\nP elétrica = P eixo / rendimento. Partida usa corrente e FP declarados, separados da demanda normal. Campos vazios de FP/limite e valores zero de corrente/tempo significam dados desconhecidos. O limite de partida é próprio; não herda o limite em regime permanente."};
   var body=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(16,0,16,0)};var table=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=2};table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,310));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));body.Controls.Add(table);
   phases.DropDownStyle=ComboBoxStyle.DropDownList;phases.Items.AddRange(new object[]{PhaseMode.Monofasico,PhaseMode.Trifasico});Row(table,"Tipo do circuito",phases);phases.SelectedItem=c.Phases;
   Number(table,"Voltage","Tensão do motor (V)");Number(table,"NominalPF","FP nominal (0 a 1)");Number(table,"Shaft","Potência mecânica no eixo (kW)");Number(table,"Efficiency","Rendimento (0 a 1)");Number(table,"Current","Corrente RMS de partida (A; 0=desconhecida)");Number(table,"StartPF","FP na partida (vazio=desconhecido)");Number(table,"Seconds","Duração declarada (s; 0=desconhecida)");Number(table,"Limit","Limite de variação na partida (%)");Row(table,"Fonte / revisão dos dados",reference);reference.MaxLength=2000;
   var data=c.MotorStarting==null?new MotorStartingData{ShaftKw=Math.Max(.000001,c.PowerKw),Efficiency=1}:c.MotorStarting.Copy();Put("Voltage",c.Voltage);Put("NominalPF",c.PowerFactor);Put("Shaft",data.ShaftKw);Put("Efficiency",data.Efficiency);Put("Current",data.StartingCurrentA);Put("Seconds",data.StartingSeconds);numbers["StartPF"].Text=data.StartingPowerFactor.HasValue?data.StartingPowerFactor.Value.ToString("R",CultureInfo.CurrentCulture):"";numbers["Limit"].Text=data.AllowedStartDropPercent.HasValue?data.AllowedStartDropPercent.Value.ToString("R",CultureInfo.CurrentCulture):"";reference.Text=data.Source;
   phases.SelectedIndexChanged+=delegate{Put("Voltage",phases.SelectedItem is PhaseMode&&(PhaseMode)phases.SelectedItem==PhaseMode.Trifasico?board.Voltage:Math.Round(board.Voltage/Math.Sqrt(3),1));};
   var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=60,Padding=new Padding(12),FlowDirection=FlowDirection.RightToLeft};var apply=new Button{Text="Aplicar motor",AutoSize=true};var cancel=new Button{Text="Cancelar",AutoSize=true,DialogResult=DialogResult.Cancel};var remove=new Button{Text="Remover modelo",AutoSize=true,Enabled=c.MotorStarting!=null};
   apply.Click+=delegate{try{ApplyValues();DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Confira os dados do motor",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};remove.Click+=delegate{MotorStarting.Remove(circuit);Changed=true;DialogResult=DialogResult.OK;};buttons.Controls.Add(apply);buttons.Controls.Add(cancel);buttons.Controls.Add(remove);CancelButton=cancel;Controls.Add(body);Controls.Add(note);Controls.Add(buttons);
  }
  static void Row(TableLayoutPanel table,string title,Control input){int row=table.RowCount++;table.RowStyles.Add(new RowStyle(SizeType.Absolute,47));table.Controls.Add(new Label{Text=title,AutoSize=true,MaximumSize=new Size(300,0),Anchor=AnchorStyles.Left},0,row);input.Dock=DockStyle.Fill;input.Margin=new Padding(4,8,4,8);table.Controls.Add(input,1,row);}
  void Number(TableLayoutPanel table,string key,string title){var box=new TextBox();numbers.Add(key,box);Row(table,title,box);}
  void Put(string key,double value){numbers[key].Text=value.ToString("R",CultureInfo.CurrentCulture);}
  double Get(string key){double number;string text=numbers[key].Text.Trim();if(text.Contains(",")&&text.Contains("."))throw new InvalidDataException("Número ambíguo em "+key+".");if(!Double.TryParse(text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out number)||Double.IsNaN(number)||Double.IsInfinity(number))throw new InvalidDataException("Valor inválido em "+key+".");return number;}
  void ApplyValues(){if(!(phases.SelectedItem is PhaseMode))throw new InvalidDataException("Selecione o tipo do circuito.");var data=new MotorStartingData{ShaftKw=Get("Shaft"),Efficiency=Get("Efficiency"),StartingCurrentA=Get("Current"),StartingSeconds=Get("Seconds"),StartingPowerFactor=String.IsNullOrWhiteSpace(numbers["StartPF"].Text)?(double?)null:Get("StartPF"),AllowedStartDropPercent=String.IsNullOrWhiteSpace(numbers["Limit"].Text)?(double?)null:Get("Limit"),Source=reference.Text};MotorStarting.Apply(project,board,circuit,data,(PhaseMode)phases.SelectedItem,Get("Voltage"),Get("NominalPF"));Changed=true;}
 }
}
